const AuthContext = createContext(null);

export function App() {
  const [user, setUser] = useState(null);
  return <AuthContext value={user}><Routes /></AuthContext>;
}

function Avatar() {                  // any depth, no intermediate props
  const user = useContext(AuthContext);
  return <img src={user.avatarUrl} alt={user.name} />;
}

// Vue 3
provide('user', user);              // ancestor
const user = inject('user');        // any descendant

// Svelte
const [getUser, setUser] = createContext();
setUser(user);                      // ancestor (during init)
